398→// Helper functions for hook management
399→
400→func hookCommandExists(matchers []ClaudeHookMatcher, command string) bool {
401→	for _, matcher := range matchers {
402→		for _, hook := range matcher.Hooks {
403→			if hook.Command == command {
404→				return true
405→			}
406→		}
407→	}
408→	return false
409→}
410→
411→func hookCommandExistsWithMatcher(matchers []ClaudeHookMatcher, matcherName, command string) bool {
412→	for _, matcher := range matchers {
413→		if matcher.Matcher == matcherName {
414→			for _, hook := range matcher.Hooks {
415→				if hook.Command == command {
416→					return true
417→				}
418→			}
419→		}
420→	}
421→	return false
422→}
423→
424→func addHookToMatcher(matchers []ClaudeHookMatcher, matcherName, command string) []ClaudeHookMatcher {
425→	entry := ClaudeHookEntry{
426→		Type:    "command",
427→		Command: command,
428→	}
429→
430→	// If no matcher name, add to a matcher with empty string
431→	if matcherName == "" {
432→		for i, matcher := range matchers {
433→			if matcher.Matcher == "" {
434→				matchers[i].Hooks = append(matchers[i].Hooks, entry)
435→				return matchers
436→			}
437→		}
438→		return append(matchers, ClaudeHookMatcher{
439→			Matcher: "",
440→			Hooks:   []ClaudeHookEntry{entry},
441→		})
442→	}
443→
444→	// Find or create matcher with the given name
445→	for i, matcher := range matchers {
446→		if matcher.Matcher == matcherName {
447→			matchers[i].Hooks = append(matchers[i].Hooks, entry)
448→			return matchers
449→		}
450→	}
451→
452→	return append(matchers, ClaudeHookMatcher{
453→		Matcher: matcherName,
454→		Hooks:   []ClaudeHookEntry{entry},
455→	})
456→}
