458→// isEntireHook checks if a command is an Entire hook (old or new format)
459→func isEntireHook(command string) bool {
460→	for _, prefix := range entireHookPrefixes {
461→		if strings.HasPrefix(command, prefix) {
462→			return true
463→		}
464→	}
465→	return false
466→}
467→
468→// removeEntireHooks removes all Entire hooks from a list of matchers (for simple hooks like Stop)
469→func removeEntireHooks(matchers []ClaudeHookMatcher) []ClaudeHookMatcher {
470→	result := make([]ClaudeHookMatcher, 0, len(matchers))
471→	for _, matcher := range matchers {
472→		filteredHooks := make([]ClaudeHookEntry, 0, len(matcher.Hooks))
473→		for _, hook := range matcher.Hooks {
474→			if !isEntireHook(hook.Command) {
475→				filteredHooks = append(filteredHooks, hook)
476→			}
477→		}
478→		// Only keep the matcher if it has hooks remaining
479→		if len(filteredHooks) > 0 {
480→			matcher.Hooks = filteredHooks
481→			result = append(result, matcher)
482→		}
483→	}
484→	return result
485→}
486→
487→// removeEntireHooksFromMatchers removes Entire hooks from tool-use matchers (PreToolUse, PostToolUse)
488→// This handles the nested structure where hooks are grouped by tool matcher (e.g., "Task", "TodoWrite")
489→func removeEntireHooksFromMatchers(matchers []ClaudeHookMatcher) []ClaudeHookMatcher {
490→	// Same logic as removeEntireHooks - both work on the same structure
491→	return removeEntireHooks(matchers)
492→}
