188→
189→// stopHookSentinel is the string that appears in Claude Code's hook_progress
190→// entry when the stop hook has been invoked, indicating the transcript is fully flushed.
191→const stopHookSentinel = "hooks claude-code stop"
192→
193→// waitForTranscriptFlush polls the transcript file for the stop hook sentinel.
194→// Falls back silently after a timeout.
195→func waitForTranscriptFlush(ctx context.Context, transcriptPath string, hookStartTime time.Time) {
196→	const (
197→		maxWait      = 3 * time.Second
198→		pollInterval = 50 * time.Millisecond
199→		tailBytes    = 4096
200→		maxSkew      = 2 * time.Second
201→	)
202→
203→	logCtx := logging.WithComponent(ctx, "agent.claudecode")
204→
205→	// Fast path: skip the poll loop when the sentinel can't possibly appear.
206→	// - File doesn't exist: nothing to poll.
207→	// - File is stale (unmodified for 2+ min): agent isn't running anymore.
208→	//   This avoids 3s timeouts per stale "active" session (e.g., agent crashed
209→	//   without firing stop hook).
210→	const staleThreshold = 2 * time.Minute
211→	info, err := os.Stat(transcriptPath)
212→	if err != nil {
213→		// Most likely the file doesn't exist; other errors (permission, etc.)
214→		// would also prevent polling, so skip the wait either way.
215→		return
216→	}
217→	fileAge := time.Since(info.ModTime())
218→	if fileAge > staleThreshold {
219→		logging.Debug(logCtx, "transcript file is stale, skipping sentinel wait",
220→			slog.Duration("file_age", fileAge),
221→		)
222→		return
223→	}
224→
225→	deadline := time.Now().Add(maxWait)
226→	for time.Now().Before(deadline) {
227→		if checkStopSentinel(transcriptPath, tailBytes, hookStartTime, maxSkew) {
228→			logging.Debug(logCtx, "transcript flush sentinel found",
229→				slog.Duration("wait", time.Since(hookStartTime)),
230→			)
231→			return
232→		}
233→		time.Sleep(pollInterval)
234→	}
235→	logging.Warn(logCtx, "transcript flush sentinel not found within timeout, proceeding",
236→		slog.Duration("timeout", maxWait),
237→	)
238→}
239→
240→// checkStopSentinel reads the tail of the transcript file and looks for the sentinel.
241→func checkStopSentinel(path string, tailBytes int64, hookStartTime time.Time, maxSkew time.Duration) bool {
242→	f, err := os.Open(path) //nolint:gosec // path comes from agent hook input
243→	if err != nil {
244→		return false
245→	}
246→	defer f.Close()
247→
248→	info, err := f.Stat()
249→	if err != nil {
250→		return false
251→	}
252→	offset := info.Size() - tailBytes
253→	if offset < 0 {
254→		offset = 0
255→	}
256→	buf := make([]byte, info.Size()-offset)
257→	if _, err := f.ReadAt(buf, offset); err != nil {
258→		return false
259→	}
260→
261→	lines := strings.Split(string(buf), "\n")
262→	for _, line := range lines {
263→		line = strings.TrimSpace(line)
264→		if line == "" || !strings.Contains(line, stopHookSentinel) {
265→			continue
266→		}
267→
268→		var entry struct {
269→			Timestamp string `json:"timestamp"`
270→		}
271→		if json.Unmarshal([]byte(line), &entry) != nil || entry.Timestamp == "" {
272→			continue
273→		}
274→		ts, err := time.Parse(time.RFC3339Nano, entry.Timestamp)
275→		if err != nil {
276→			ts, err = time.Parse(time.RFC3339, entry.Timestamp)
277→			if err != nil {
278→				continue
279→			}
280→		}
281→		// Validate timestamp is within acceptable range:
282→		// - Not too far in the past (before hook started minus skew)
283→		// - Not too far in the future (after hook started plus skew)
284→		lowerBound := hookStartTime.Add(-maxSkew)
285→		upperBound := hookStartTime.Add(maxSkew)
286→		if ts.After(lowerBound) && ts.Before(upperBound) {
287→			return true
288→		}
289→	}
290→	return false
291→}
