func (s *ManualCommitStrategy) resolveFilesTouched(ctx context.Context, state *SessionState) []string {
	// Merge state.FilesTouched (from SaveStep at turn boundaries) with
	// the tracking file (from post-file-edit hook in real-time).
	var tracked []string
	if store, err := s.getStateStore(ctx); err == nil {
		tracked, _ = store.ReadFilesTouched(ctx, state.SessionID)
	}

	if len(state.FilesTouched) > 0 || len(tracked) > 0 {
		seen := make(map[string]struct{})
		var result []string
		for _, f := range state.FilesTouched {
			if _, ok := seen[f]; !ok {
				seen[f] = struct{}{}
				result = append(result, f)
			}
		}
		for _, f := range tracked {
			if _, ok := seen[f]; !ok {
				seen[f] = struct{}{}
				result = append(result, f)
			}
		}
		sort.Strings(result)
		return result
	}

	// Fall back to transcript extraction
	prepareTranscriptForState(ctx, state)
	return s.extractModifiedFilesFromLiveTranscript(ctx, state, state.CheckpointTranscriptStart)
}
