1464→// Handles PrepareTranscript internally before falling back to extraction,
1465→// so callers don't need to prepare the transcript first.
1466→func (s *ManualCommitStrategy) resolveFilesTouched(ctx context.Context, state *SessionState) []string {
1467→	logCtx := logging.WithComponent(ctx, "checkpoint")
1468→	var tracked []string
1469→	if store, err := s.getStateStore(ctx); err != nil {
1470→		logging.Debug(logCtx, "resolveFilesTouched: could not get state store, falling back to transcript",
1471→			slog.String("session_id", state.SessionID),
1472→			slog.String("error", err.Error()),
1473→		)
1474→	} else if files, readErr := store.ReadFilesTouched(ctx, state.SessionID); readErr != nil {
1475→		logging.Debug(logCtx, "resolveFilesTouched: could not read tracking file, falling back to transcript",
1476→			slog.String("session_id", state.SessionID),
1477→			slog.String("error", readErr.Error()),
1478→		)
1479→	} else {
1480→		tracked = files
1481→	}
1482→
1483→	if len(state.FilesTouched) > 0 || len(tracked) > 0 {
1484→		seen := make(map[string]struct{})
1485→		var result []string
1486→		for _, f := range append(state.FilesTouched, tracked...) {
1487→			if _, ok := seen[f]; !ok {
1488→				seen[f] = struct{}{}
1489→				result = append(result, f)
1490→			}
1491→		}
1492→		sort.Strings(result)
1493→		return result
1494→	}
1495→
1496→	// Prepare transcript before extraction (e.g., OpenCode `opencode export`).
1497→	prepareTranscriptForState(ctx, state)
1498→
1499→	return s.extractModifiedFilesFromLiveTranscript(ctx, state, state.CheckpointTranscriptStart)
1500→}
