 63→// ReadTranscript reads the raw JSON transcript bytes for a session.
 64→func (g *GeminiCLIAgent) ReadTranscript(sessionRef string) ([]byte, error) {
 65→	data, err := os.ReadFile(sessionRef) //nolint:gosec // Path comes from agent hook input
 66→	if err != nil {
 67→		return nil, fmt.Errorf("failed to read transcript: %w", err)
 68→	}
 69→	return data, nil
